// Package csvutil provides CSV file reading and writing utilities.
package csvutil

import (
	"encoding/csv"
	"os"
	"strings"
)

// ParseCSV reads a CSV file and returns all records.
func ParseCSV(path string) ([][]string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	r := csv.NewReader(strings.NewReader(string(data)))
	return r.ReadAll()
}

// WriteCSV writes records to a CSV file, creating or overwriting it.
// BUG: wrong file permission (0o444 = read-only; should be 0o644)
func WriteCSV(path string, rows [][]string) error {
	var sb strings.Builder
	w := csv.NewWriter(&sb)
	if err := w.WriteAll(rows); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(sb.String()), 0o444)
}

// CountRows returns the number of data rows (excluding header) in a CSV file.
// BUG: returns len(records) instead of len(records) - 1 (includes header in count)
func CountRows(path string) (int, error) {
	records, err := ParseCSV(path)
	if err != nil {
		return 0, err
	}
	if len(records) == 0 {
		return 0, nil
	}
	return len(records), nil
}

// FilterCSV reads a CSV file and returns rows where pred returns true.
// BUG: panics on empty CSV — accesses records[0] without nil check
func FilterCSV(path string, pred func([]string) bool) ([][]string, error) {
	records, err := ParseCSV(path)
	if err != nil {
		return nil, err
	}
	result := [][]string{records[0]}
	for _, row := range records[1:] {
		if pred(row) {
			result = append(result, row)
		}
	}
	return result, nil
}
